<script setup lang="ts">
import AdminLayout from '@/Layouts/AdminLayout.vue'; import InputError from '@/Components/InputError.vue'; import { Head, Link, useForm } from '@inertiajs/vue3'; interface Shipment { id:number; status:string; carrier:string|null; tracking_code:string|null; order:{number:string;user:{name:string}}|null;} interface Status {value:string;label:string;} const props=defineProps<{shipment:Shipment;statuses:Status[]}>(); const form=useForm({status:props.shipment.status,carrier:props.shipment.carrier??'',tracking_code:props.shipment.tracking_code??''}); function submit():void{form.put(`/admin/shipments/${props.shipment.id}`)}
</script>
<template><Head title="Editar envio"/><AdminLayout><Link href="/admin/shipments" class="text-sm font-bold text-sky-700">← Envios</Link><div class="mt-5"><p class="text-xs font-bold uppercase tracking-[.16em] text-sky-500">Pedido {{ shipment.order?.number }}</p><h1 class="mt-2 text-3xl font-black text-slate-950">Atualizar envio</h1><p class="mt-2 text-sm text-slate-500">Cliente: {{ shipment.order?.user.name }}</p></div><form class="mt-8 max-w-2xl rounded-2xl border border-slate-200 bg-white p-6 shadow-sm" @submit.prevent="submit"><div class="grid gap-5 sm:grid-cols-2"><div><label class="mb-2 block text-sm font-bold text-slate-700">Status</label><select v-model="form.status" class="w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-sky-500"><option v-for="status in statuses" :key="status.value" :value="status.value">{{ status.label }}</option></select><InputError :message="form.errors.status"/></div><div><label class="mb-2 block text-sm font-bold text-slate-700">Transportadora</label><input v-model="form.carrier" class="w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-sky-500" placeholder="Ex.: Correios"></div><div class="sm:col-span-2"><label class="mb-2 block text-sm font-bold text-slate-700">Código de rastreio</label><input v-model="form.tracking_code" class="w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-sky-500" placeholder="Ex.: BR123456789"></div></div><button type="submit" :disabled="form.processing" class="mt-6 rounded-xl bg-sky-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-sky-500 disabled:opacity-60">Salvar envio</button></form></AdminLayout></template>
